function next_cursor(array $rows, string $orderBy): ?string
{
    if ($rows === []) {
        return null;                     // empty page -> no next page
    }

    $last = end($rows);                  // rows arrive sorted by $orderBy

    return base64_encode((string) $last[$orderBy]);
}

function decode_cursor(?string $cursor): ?array
{
    if ($cursor === null || $cursor === '') {
        return null;                      // sentinel: no further page
    }

    $raw = base64_decode($cursor, true);  // strict: false on bad base64

    if ($raw === false) {
        return null;                      // malformed input
    }

    $decoded = json_decode($raw, true);

    return is_array($decoded) ? $decoded : null;
}

