function rate_limit_ok(array $timestamps, int $limit, int $windowSeconds, int $now): bool
{
    $windowStart = $now - $windowSeconds;

    $count = 0;
    foreach ($timestamps as $t) {
        if ($t > $windowStart) {   // strictly inside the window
            $count++;
        }
    }

    return $count < $limit;
}
